import { spawn } from 'node:child_process';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import { Failure } from './errors.js';
const MAX_TEXT = 200_000;
const SHELL_TIMEOUT_MS = 120_000;
const FETCH_TIMEOUT_MS = 30_000;
const MAX_REDIRECTS = 5;
/** Characters that let a command chain, redirect or substitute; rejected while any restriction is active. */
const SHELL_META = /[&|;<>`$()\r\n^%!]/;
export const TOOL_SPECS = {
    read_file: {
        name: 'read_file',
        description: 'Read a UTF-8 text file and return its content.',
        properties: { path: { type: 'string', description: 'Path of the file to read' } },
        required: ['path'],
    },
    write_file: {
        name: 'write_file',
        description: 'Create or overwrite a UTF-8 text file (parent folders are created).',
        properties: {
            path: { type: 'string', description: 'Path of the file to write' },
            content: { type: 'string', description: 'Complete new content of the file' },
        },
        required: ['path', 'content'],
    },
    web_fetch: {
        name: 'web_fetch',
        description: 'Fetch an http(s) URL with GET and return the response body as text.',
        properties: { url: { type: 'string', description: 'URL to fetch' } },
        required: ['url'],
    },
    web_search: {
        name: 'web_search',
        description: 'Search the web and return the top results (title, URL and snippet).',
        properties: { query: { type: 'string', description: 'Search query' } },
        required: ['query'],
    },
    shell: {
        name: 'shell',
        description: 'Run a shell command and return its combined output.',
        properties: { command: { type: 'string', description: 'Command line to run' } },
        required: ['command'],
    },
};
function needString(tool, params, name) {
    const v = params[name];
    if (typeof v !== 'string' || v === '')
        throw new Failure('tool_error', `${tool}: parameter '${name}' must be a non-empty string`);
    return v;
}
function truncate(text) {
    return text.length > MAX_TEXT ? `${text.slice(0, MAX_TEXT)}\n...[truncated ${text.length - MAX_TEXT} characters]` : text;
}
/** Splits a simple command line, honoring '...' and "..." quoting. No escapes, no expansion. */
export function splitCommand(command) {
    const args = [];
    let cur = '';
    let inToken = false;
    let quote;
    for (const ch of command) {
        if (quote) {
            if (ch === quote)
                quote = undefined;
            else
                cur += ch;
        }
        else if (ch === '"' || ch === "'") {
            quote = ch;
            inToken = true;
        }
        else if (/\s/.test(ch)) {
            if (inToken)
                args.push(cur);
            cur = '';
            inToken = false;
        }
        else {
            cur += ch;
            inToken = true;
        }
    }
    if (quote)
        throw new Failure('restriction_violation', 'shell command rejected: unterminated quote');
    if (inToken)
        args.push(cur);
    return args;
}
const SEARCH_ENDPOINT = 'https://html.duckduckgo.com/html/';
const MAX_SEARCH_RESULTS = 10;
const decodeEntities = (s) => s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&');
const plainText = (html) => decodeEntities(html.replace(/<[^>]*>/g, '')).replace(/\s+/g, ' ').trim();
/** Extracts result links from DuckDuckGo's HTML results page; result links are redirects carrying the target in `uddg`. */
export function parseSearchResults(html) {
    const results = [];
    const link = /<a[^>]*class="result__a"[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/g;
    const snippets = [...html.matchAll(/<a[^>]*class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g)];
    let m;
    let i = 0;
    while ((m = link.exec(html)) && results.length < MAX_SEARCH_RESULTS) {
        const href = decodeEntities(m[1]);
        let url = href;
        try {
            const u = new URL(href, 'https://duckduckgo.com');
            url = u.searchParams.get('uddg') ?? u.href;
        }
        catch {
            // keep the raw href
        }
        results.push({ title: plainText(m[2]), url, snippet: snippets[i] ? plainText(snippets[i][1]) : '' });
        i++;
    }
    return results;
}
const looksLikeUrl = (s) => /^[a-z][a-z0-9+.-]*:\/\//i.test(s);
const looksLikePath = (s) => /[\\/]/.test(s) || s.startsWith('.') || s.startsWith('~') || /^[a-z]:/i.test(s);
/**
 * Executes the built-in tools. Every call is checked against the active restrictions,
 * whether it comes from the script itself or from the LLM.
 */
export class ToolHost {
    restrictions;
    cwd;
    constructor(restrictions, cwd) {
        this.restrictions = restrictions;
        this.cwd = cwd;
    }
    async invoke(name, params) {
        switch (name) {
            case 'read_file': return this.readFile(needString(name, params, 'path'));
            case 'write_file': {
                const content = params.content;
                if (typeof content !== 'string')
                    throw new Failure('tool_error', "write_file: parameter 'content' must be a string");
                return this.writeFile(needString(name, params, 'path'), content);
            }
            case 'web_fetch': return this.webFetch(needString(name, params, 'url'));
            case 'web_search': return this.webSearch(needString(name, params, 'query'));
            case 'shell': return this.shell(needString(name, params, 'command'));
        }
    }
    async readFile(p) {
        const canonical = this.restrictions.checkPath(p, 'read');
        try {
            return truncate(await fs.readFile(canonical, 'utf8'));
        }
        catch (e) {
            throw new Failure('tool_error', `read_file '${p}': ${e.message}`);
        }
    }
    async writeFile(p, content) {
        const canonical = this.restrictions.checkPath(p, 'write');
        try {
            await fs.mkdir(path.dirname(canonical), { recursive: true });
            await fs.writeFile(canonical, content, 'utf8');
        }
        catch (e) {
            throw new Failure('tool_error', `write_file '${p}': ${e.message}`);
        }
        return `Wrote ${Buffer.byteLength(content)} bytes to ${canonical}`;
    }
    async webFetch(url) {
        let current = this.restrictions.checkUrl(url);
        for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
            let res;
            try {
                res = await fetch(current, { redirect: 'manual', signal: AbortSignal.timeout(FETCH_TIMEOUT_MS) });
            }
            catch (e) {
                throw new Failure('tool_error', `web_fetch '${current.href}': ${e.message}`);
            }
            if (res.status >= 300 && res.status < 400 && res.headers.get('location')) {
                current = this.restrictions.checkUrl(new URL(res.headers.get('location'), current).href);
                continue;
            }
            const body = truncate(await res.text());
            if (!res.ok)
                throw new Failure('tool_error', `web_fetch '${current.href}': HTTP ${res.status}\n${body}`);
            return body;
        }
        throw new Failure('tool_error', `web_fetch '${url}': too many redirects`);
    }
    /** Searches DuckDuckGo's HTML endpoint (no API key); it is a network call, so `restrict net` applies to it. */
    async webSearch(query) {
        const url = this.restrictions.checkUrl(`${SEARCH_ENDPOINT}?q=${encodeURIComponent(query)}`);
        let html;
        try {
            const res = await fetch(url, {
                headers: { 'user-agent': 'Mozilla/5.0 (compatible; spl-lang)' },
                signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
            });
            if (!res.ok)
                throw new Error(`HTTP ${res.status}`);
            html = await res.text();
        }
        catch (e) {
            throw new Failure('tool_error', `web_search '${query}': ${e.message}`);
        }
        const results = parseSearchResults(html);
        if (results.length === 0)
            return `No results for "${query}".`;
        return results.map((r, i) => `${i + 1}. ${r.title}\n   ${r.url}${r.snippet ? `\n   ${r.snippet}` : ''}`).join('\n');
    }
    async shell(command) {
        if (!this.restrictions.active)
            return this.run(command, { shell: true });
        // With any restriction active only plain commands are accepted, so the checks below are exact.
        if (SHELL_META.test(command)) {
            throw new Failure('restriction_violation', 'shell command rejected: chaining, redirection and substitution are not allowed inside a restrict block');
        }
        const argv = splitCommand(command);
        if (argv.length === 0)
            throw new Failure('tool_error', 'shell: empty command');
        this.restrictions.checkExec(argv[0]);
        for (const arg of argv.slice(1)) {
            const value = arg.startsWith('-') && arg.includes('=') ? arg.slice(arg.indexOf('=') + 1) : arg;
            if (looksLikeUrl(value)) {
                if (this.restrictions.has('net'))
                    this.restrictions.checkHost(new URL(value).hostname.toLowerCase());
            }
            else if (this.restrictions.has('fs') && value && !value.startsWith('-') && looksLikePath(value)) {
                this.restrictions.checkPath(value, 'read');
            }
        }
        if (argv.some((a) => a.includes('"'))) {
            throw new Failure('restriction_violation', 'shell command rejected: embedded double quotes are not allowed inside a restrict block');
        }
        if (process.platform === 'win32') {
            // .cmd shims (npm, ...) need a shell on Windows; metacharacters were already rejected.
            return this.run(argv.map((a) => (/\s/.test(a) || a === '' ? `"${a}"` : a)).join(' '), { shell: true });
        }
        return this.run(argv[0], { shell: false, args: argv.slice(1) });
    }
    run(command, opts) {
        return new Promise((resolve, reject) => {
            const child = spawn(command, opts.args ?? [], { cwd: this.cwd, shell: opts.shell, windowsHide: true });
            let out = '';
            const collect = (d) => {
                if (out.length < MAX_TEXT * 2)
                    out += d.toString('utf8');
            };
            child.stdout.on('data', collect);
            child.stderr.on('data', collect);
            const timer = setTimeout(() => child.kill(), SHELL_TIMEOUT_MS);
            child.on('error', (e) => {
                clearTimeout(timer);
                reject(new Failure('tool_error', `shell: ${e.message}`));
            });
            child.on('close', (code, signal) => {
                clearTimeout(timer);
                const text = truncate(out);
                if (code === 0)
                    resolve(text);
                else
                    reject(new Failure('tool_error', `shell: ${signal ? `terminated by ${signal}` : `exit code ${code}`}\n${text}`));
            });
        });
    }
}
